<?php if ($preview): $suggestion=$preview['suggestion']; ?><div class="notice" role="status"><?php if ($suggestion): ?><?= e(t('Suggested:')) ?> <strong><?= e($suggestion['category']) ?></strong><?= e(t('. Matched the rule “')) ?><?= e($suggestion['keyword']) ?>”.<?php else: ?><strong><?= e(t('Uncategorized.')) ?></strong> <?= e(t('No enabled rule matched. Choose a category below.')) ?><?php endif; ?></div><form method="post" action="/expenses" class="stack"><?= csrf_field() ?><label><?= e(t('Date')) ?><input type="date" name="date" value="<?= e(ui_date('Y-m-d')) ?>" required></label><label><?= e(t('Amount (Rs.)')) ?><input type="number" name="amount" min="0.01" max="9999999999.99" step="0.01" required></label><label><?= e(t('Category')) ?><select name="category" required><option value=""><?= e(t('Choose category')) ?></option><?php foreach ($categories as $category): ?><option value="<?= e($category['id']) ?>" <?= $suggestion && $suggestion['category_id']===(int)$category['id'] ? 'selected' : '' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select></label><label><?= e(t('From account')) ?><select name="account" required><?php foreach ($accounts as $account): ?><option value="<?= e($account['id']) ?>"><?= e($account['name']) ?></option><?php endforeach; ?></select></label><label><?= e(t('Note')) ?><input name="note" maxlength="1000" value="<?= e($preview['description']) ?>"></label><p class="muted"><?= e(t('Check the amount, account and category. Saving posts one real expense and debits the selected account.')) ?></p><button><?= e(t('Save reviewed expense')) ?></button></form><?php endif; ?></section>
</div>
<section class="card"><h2><?= e(t('Ordered rules')) ?></h2><?php if (!$rules): ?><div class="empty"><h3><?= e(t('No rules yet.')) ?></h3><p><?= e(t('Add a keyword above. Descriptions without a match stay uncategorized until you choose a category.')) ?></p></div><?php else: ?><div class="table-wrap"><table><thead><tr><th><?= e(t('Priority')) ?></th><th><?= e(t('Keyword')) ?></th><th><?= e(t('Category')) ?></th><th><?= e(t('Status')) ?></th><th><?= e(t('Actions')) ?></th></tr></thead><tbody><?php foreach ($rules as $rule): ?><tr><td><?= e($rule['priority']) ?></td><td><strong><?= e($rule['keyword']) ?></strong></td><td><?= e($rule['category']) ?></td><td><?= $rule['enabled'] ? t('Enabled') : t('Paused') ?></td><td><div class="hero-actions"><a href="/salary/expense-rules?edit=<?= e($rule['id']) ?>"><?= e(t('Edit')) ?></a><form method="post" action="/salary/expense-rules/<?= e($rule['id']) ?>/delete" data-confirm="Remove this category rule?"><?= csrf_field() ?><button class="quiet"><?= e(t('Remove')) ?></button></form></div></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
